@CrossOrigin
@RestController
@RequestMapping("/TagQuery")
public class TagQueryRestController extends BaseSpringRestController {
	
	public TagQueryRestController( TagService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Tag using a UUID
     * @param		UUID tagId
     * @return		Tag
     */    
    @GetMapping("/load")
    public Tag load( @RequestParam(required=true) UUID tagId ) {
    	Tag entity = null;

    	try {  
    		entity = service.getTag( new TagFetchOneSummary( tagId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Tag using Id " + tagId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Tag business objects
     * @return		Set<Tag>
     */
    @GetMapping("/")
    public List<Tag> loadAll() {                
    	List<Tag> tagList = null;
        
    	try {
            // load the Tag
            tagList = service.getAllTag();
            
            if ( tagList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Tags" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Tags ", exc );
        	return null;
        }

        return tagList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Tag tag = null;
    protected TagService service = null;
    private static final Logger LOGGER = Logger.getLogger(TagQueryRestController.class.getName());
    
}
